<?php foreach ((array) ($workflow['taxonomy_proposals'] ?? []) as $pendingTaxonomy): if (!is_array($pendingTaxonomy)) continue; ?><p><strong>Taxonomy proposal pending:</strong> <?= $e($pendingTaxonomy['kind'] ?? '') ?> “<?= $e($pendingTaxonomy['label'] ?? '') ?>” under <?= $e($pendingTaxonomy['parent_id'] ?? '') ?> · <?= $e($pendingTaxonomy['status'] ?? '') ?> · <?= $e($pendingTaxonomy['rationale'] ?? '') ?></p><?php endforeach; ?></section>

<section id="study-review" class="card"><h2>Study relationship</h2><p><strong>B695 proposal:</strong> <?= $e($original['study_relationship']['material_title'] ?? $original['study_relationship']['material_id'] ?? 'No material') ?> · <?= $e($original['study_relationship']['section_heading'] ?? $original['study_relationship']['section_id'] ?? 'No exact section') ?> · <?= !empty($original['study_relationship']['current_section_exists']) ? 'present in B713 snapshot' : 'missing in B713 snapshot' ?></p><?php if ($study !== []): ?><p><strong>Finding:</strong> <?= $e($study['status'] ?? '') ?> · <?= $e($study['material_id'] ?? '') ?> / <?= $e($study['section_id'] ?? '') ?> · <?= $e($study['rationale'] ?? '') ?></p><?php endif; ?><p>Study content is optional for import. A proposal-only section is never represented as a current lesson.</p>
<?php if (!empty($can['STUDY_LINK'])): $form('/developer/academic-review/study-link'); ?><label>Study-link status<select name="status"><option value="UNRESOLVED">Unresolved</option><option value="OPTIONAL_ENRICHMENT">Optional enrichment not linked</option><option value="APPROVED_EXACT_LINK">Approve exact existing material section link</option></select></label><label>Material ID<input name="material_id" value="<?= $e($original['study_relationship']['material_id'] ?? '') ?>"></label><label>Exact section ID<input name="section_id" value="<?= $e($original['study_relationship']['section_id'] ?? '') ?>"></label><label>Evidence and board/subject fit<textarea name="rationale" minlength="20" required></textarea></label><button type="submit">Record study-link review</button></form><?php endif; ?></section>

<section id="review-actions" class="card"><h2>Assignment</h2><p>Authenticated account: <?= $e($accountId) ?>. The server assigns this account; client identity fields are not accepted.</p><?php if (!empty($can['REVIEW']) && in_array(($workflow['state'] ?? 'PENDING_REVIEW'), ['PENDING_REVIEW','DEFERRED','ASSIGNED'], true)): $form('/developer/academic-review/assign'); ?><button type="submit">Assign to me</button></form><?php endif; ?><?php if (!empty($can['REVIEW']) && ($workflow['state'] ?? '') === 'ASSIGNED' && ($workflow['assigned_reviewer_id'] ?? '') === $accountId): $form('/developer/academic-review/start'); ?><button type="submit">Start review</button></form><?php endif; ?></section>

<?php if (!empty($can['REVIEW']) && ($workflow['state'] ?? '') === 'IN_REVIEW' && ($workflow['assigned_reviewer_id'] ?? '') === $accountId): ?><section class="card"><h2>Record academic decision</h2><p>Approval applies to version <?= $e(substr($version, 0, 16)) ?> only. Source verification remains a separate gate.</p><?php $form('/developer/academic-review/decision'); ?><label>Decision<select name="decision"><option value="APPROVE">Approve exact version</option><option value="REQUEST_REVISION">Request revision</option><option value="REJECT">Reject</option><option value="DEFER">Defer</option></select></label><label>Reasoned rationale<textarea name="rationale" minlength="20" required></textarea></label><fieldset><legend>Approval checks</legend><?php foreach (['question_accuracy'=>'Question is accurate','correct_answer'=>'Proposed answer is correct','explanation_correctness'=>'Explanation is correct','exam_relevance'=>'Relevant to this examination','subject_classification'=>'Subject classification is correct','adequate_source_support'=>'Source evidence supports the item-level claim','source_currentness'=>'Required source currentness is confirmed'] as $key => $label): ?><label><input type="checkbox" name="<?= $key ?>" value="1"> <?= $e($label) ?></label><?php endforeach; ?><?php if (in_array(strtolower((string) ($proposal['board_id'] ?? '')), ['let', 'architecture'], true)): ?><label><input type="checkbox" name="regulatory_scope_currentness" value="1"> I verified this proposal against the current official examination scope/program</label><?php endif; ?><?php if (strtolower((string) ($proposal['board_id'] ?? '')) === 'nursing'): ?><label><input type="checkbox" name="clinical_safety" value="1"> I independently checked clinical safety and applicable current guidance</label><?php endif; ?></fieldset><button type="submit">Record decision</button></form></section><?php endif; ?>

<?php if (!empty($can['EDIT_PROPOSAL']) && ($workflow['state'] ?? '') === 'REVISION_REQUESTED'): ?><section class="card"><h2>Record a new proposal revision</h2><p>The original source snapshot and prior content remain unchanged. A revision invalidates prior approvals and source reviews.</p><?php $form('/developer/academic-review/revision'); ?><label>Revised stem<textarea name="stem" required><?= $e($content['stem'] ?? '') ?></textarea></label><?php foreach (array_values((array) ($content['choices'] ?? [])) as $i => $choice): ?><label>Choice <?= $i + 1 ?><input name="choices[]" value="<?= $e($choice) ?>" required></label><?php endforeach; ?><label>Proposed answer<input name="proposed_answer" value="<?= $e($content['proposed_answer'] ?? '') ?>" required></label><label>Explanation<textarea name="explanation" required><?= $e($content['explanation'] ?? '') ?></textarea></label><label>Difficulty<select name="difficulty"><?php foreach (['easy','medium','hard'] as $d): ?><option value="<?= $d ?>"<?= ($content['difficulty'] ?? '') === $d ? ' selected' : '' ?>><?= ucfirst($d) ?></option><?php endforeach; ?></select></label><label>Revision reason and provenance<textarea name="reason" minlength="20" required></textarea></label><button type="submit">Save new proposal version</button></form></section><?php endif; ?>

<?php if (is_array($preflight ?? null)): ?><section id="import-preflight" class="card"><h2>Controlled import preflight</h2><?php if (!empty($preflight['eligible'])): ?><p><strong>Ready for a separately authorized individual import.</strong> Approval alone has not published the question.</p><p>Exact canonical change preview:</p><pre><?= $e(json_encode($preflight['question'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre><?php if (!empty($preflight['study_link'])): ?><p>Also stages the approved exact study relationship <?= $e($preflight['study_link']['material_id'] ?? '') ?> / <?= $e($preflight['study_link']['section_id'] ?? '') ?>.</p><?php endif; ?><?php $form('/developer/academic-review/import'); ?><input type="hidden" name="preview_token" value="<?= $e($preflight['preview_token'] ?? '') ?>"><label><input type="checkbox" name="confirm" value="1" required> I reviewed this exact preview and authorize importing this one proposal</label><button type="submit">Import this approved proposal</button></form><?php else: ?><p><strong>Not import-ready.</strong></p><ul><?php foreach ((array) ($preflight['blocked'] ?? []) as $reason): ?><li><?= $e($reason) ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>

<section id="decision-history" class="card"><h2>Decision and audit history</h2><?php if (($workflow['decisions'] ?? []) === []): ?><p>No academic decision or source review has been recorded.</p><?php else: ?><ol><?php foreach (array_reverse((array) $workflow['decisions']) as $event): if (!is_array($event)) continue; ?><li><strong><?= $e($event['decision'] ?? '') ?></strong> · <?= $e($event['review_timestamp'] ?? '') ?> · <span class="academic-review-private-metadata">account <?= $e($event['reviewer_id'] ?? '') ?></span> · <?= $e($event['review_state_before'] ?? '') ?> → <?= $e($event['review_state_after'] ?? '') ?><p><?= $e($event['rationale'] ?? '') ?></p><small>Version <?= $e(substr((string) ($event['proposal_version'] ?? ''), 0, 16)) ?> · event digest <?= $e(substr((string) ($event['event_sha256'] ?? ''), 0, 20)) ?></small></li><?php endforeach; ?></ol><?php endif; ?>
<?php if (($workflow['revisions'] ?? []) !== []): ?><h3>Proposal revision history</h3><ol><?php foreach ($workflow['revisions'] as $revision): $priorContent = is_array($revision['proposed_question'] ?? null) ? $revision['proposed_question'] : []; ?><li><?= $e($revision['created_at'] ?? '') ?> · <span class="academic-review-private-metadata">account <?= $e($revision['created_by'] ?? '') ?></span> · <?= $e($revision['reason'] ?? '') ?> · version <?= $e(substr((string) ($revision['proposal_version'] ?? ''), 0, 16)) ?><details><summary>Inspect this preserved revision</summary><p><?= $e($priorContent['stem'] ?? '') ?></p><ol><?php foreach ((array) ($priorContent['choices'] ?? []) as $choice): ?><li><?= $e($choice) ?><?= (string) $choice === (string) ($priorContent['proposed_answer'] ?? '') ? ' · proposed answer' : '' ?></li><?php endforeach; ?></ol><p><strong>Answer:</strong> <?= $e($priorContent['proposed_answer'] ?? '') ?></p><p><strong>Explanation:</strong> <?= $e($priorContent['explanation'] ?? '') ?></p><p><strong>Difficulty:</strong> <?= $e($priorContent['difficulty'] ?? '') ?></p></details></li><?php endforeach; ?></ol><?php endif; ?></section>

</div>
<script src="/assets/js/academic-review-print.js" defer></script>
